add_filter( 'woocommerce_package_rates', 'perfectpixel_hide_rate_by_shipping_class', 10, 2 );

function perfectpixel_hide_rate_by_shipping_class( $rates, $package ) {
	$class = '{{hide_rate_class}}';
	$found = false;
	foreach ( $package['contents'] as $item ) {
		if ( ! empty( $item['data'] ) && $item['data']->get_shipping_class() === $class ) {
			$found = true;
			break;
		}
	}
	if ( ! $found ) {
		return $rates;
	}
	$targets = array_filter( array_map( 'trim', explode( ',', '{{hide_rate_methods}}' ) ) );
	foreach ( $rates as $rate_id => $rate ) {
		if ( in_array( $rate_id, $targets, true ) || in_array( $rate->get_method_id(), $targets, true ) ) {
			unset( $rates[ $rate_id ] );
		}
	}
	return $rates;
}
